import {ions,key,IonEngine,formulaHTML} from './ions-engine.mjs';
const $=id=>document.getElementById(id);let engine,saving=true;
function save(){try{if(saving)localStorage.setItem(key,JSON.stringify(engine.snapshot()));}catch{saving=false;$('ion-warning').hidden=false;$('ion-warning').textContent='Your browser cannot save ion progress. You can continue this session, but it will be lost on reload.';}$('ion-save').textContent=saving?'Ion progress saved':'Not saving';}
function render(){const s=engine.s,learning=s.view==='learn';$('ion-learn').hidden=!learning;$('ion-reference').hidden=learning;$('ion-learn-tab').classList.toggle('active',learning);$('ion-reference-tab').classList.toggle('active',!learning);$('ion-learn-tab').setAttribute('aria-pressed',String(learning));$('ion-reference-tab').setAttribute('aria-pressed',String(!learning));
 $('ion-list').innerHTML=ions.map(x=>`<div class="ion-list-item"><span>${x.name}${x.alias?' ('+x.alias+')':''}</span><strong>${formulaHTML(x)}${x.alternate?' / '+formulaHTML({...x,body:x.alternate}):''}</strong></div>`).join('');
 const missed=Object.values(s.misses).filter(n=>n>0).length;
 $('ion-progress').innerHTML=`<div class="group-header"><span>${s.reviewIds?'STUDY MISSED':'YOUR GROUP'}</span><span>${s.group+1} / ${engine.groupCount()}</span></div><h2>${s.pass===4?'Group complete': ['Recognize names','Recognize formulas','Recall names','Recall formulas'][s.pass]}</h2><p class="study-label">${s.pass===4?'Choose what to do next.':`Pass ${s.pass+1} / 4 · ${s.position+1} / ${engine.group().length}`}</p><div class="progress-row"><span>Correct answers</span><strong>${s.correct} / ${s.answers}</strong></div><div class="progress-row"><span>Different ions missed</span><strong>${missed}</strong></div><button id="ion-review" class="button secondary-button restore-postponed" ${!missed||s.reviewIds?'disabled':''}>Study missed</button>${s.reviewIds?'<button id="ion-return" class="button quiet restore-postponed">Return to learning</button>':''}<p class="saved-note" style="margin-top:18px">${saving?'Saved on this browser.':'Progress is not being saved.'}</p>`;
 if(s.pass===4){$('ion-question').innerHTML=`<p class="eyebrow">GROUP COMPLETE</p><h2>Ready to continue?</h2><p class="family-intro muted">Review the study list anytime. Your totals stay saved.</p><button id="ion-next-group" class="button primary">${s.reviewIds&&s.group===engine.groupCount()-1?'Return to learning':'Next group'}</button>`;return;}
 const q=engine.next(),ion=ions[q.id],f=s.feedback,askName=s.pass===0||s.pass===2,typed=s.pass>=2;
 const prompt=askName?formulaHTML(ion):ion.name;
 const choices=typed?`<form id="ion-form" class="answer-form"><label class="answer-label" for="ion-answer">${askName?'Ion name':'Formula with charge'}</label><input id="ion-answer" class="answer-input" type="text" maxlength="100" autocomplete="off" spellcheck="false" ${f?'disabled':''}><p class="study-label">${askName?'The word “ion” is optional.':'Use ^ for the charge, for example SO4^2- or NH4+. Capitalization matters.'}</p>${!f?'<button class="button primary" type="submit">Check answer</button>':''}</form>`:`<div class="choices">${q.options.map((id,i)=>`<button class="choice ${f&&id===q.id?'correct':''}" data-ion-answer="${id}" data-question="${q.questionId}" ${f?'disabled':''}><span class="choice-index">${i+1}</span><span>${askName?ions[id].name:formulaHTML(ions[id])}</span></button>`).join('')}</div>`;
 const feedback=f?`<div class="feedback ${f.correct?'':'incorrect'}" role="status"><h3>${f.correct?'Correct.':'Keep this one in mind.'}</h3><p>${ion.name} is <strong>${formulaHTML(ion)}</strong>${ion.alternate?' (also '+formulaHTML({...ion,body:ion.alternate})+')':''}.</p></div><div class="continue-row"><span class="saved-note">${saving?'Answer saved':'Not saving'}</span><button id="ion-continue" class="button primary">Continue</button></div>`:'';
 $('ion-question').innerHTML=`<div class="question-meta"><span>${askName?'Formula → name':'Name → formula'}</span><span class="question-tag">${typed?'Type':'Multiple choice'}</span></div><div class="question-prompt"><h2>${askName?'Name this ion':'What is its formula and charge?'}</h2><p class="${askName?'prompt-symbol ion-formula':'prompt-name'}">${prompt}</p></div>${choices}${feedback}`;
 if(typed&&!f)$('ion-answer').value=s.draft;
}
function update(fn){try{if(fn()===false)return;render();save();}catch(e){$('ion-warning').hidden=false;$('ion-warning').textContent=e.message;}}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.ionAnswer!==undefined){update(()=>engine.answer(b.dataset.ionAnswer,b.dataset.question));return;}switch(b.id){case 'ion-learn-tab':update(()=>{engine.s.view='learn';});break;case 'ion-reference-tab':update(()=>{engine.s.view='reference';});break;case 'ion-review':update(()=>engine.startReview());break;case 'ion-return':update(()=>engine.endReview());break;case 'ion-continue':update(()=>engine.advance());break;case 'ion-next-group':update(()=>engine.nextGroup());break;case 'ion-reset':$('ion-reset-dialog').showModal();break;case 'ion-confirm-reset':engine=new IonEngine();engine.next();$('ion-reset-dialog').close();render();save();break;}});
document.addEventListener('submit',e=>{if(e.target.id==='ion-form'){e.preventDefault();update(()=>engine.answer($('ion-answer').value,engine.s.current.questionId));}});
document.addEventListener('input',e=>{if(e.target.id==='ion-answer'&&!engine.s.feedback){engine.s.draft=e.target.value;save();}});
try{let saved=null,raw=null;try{raw=localStorage.getItem(key);}catch{saving=false;$('ion-warning').hidden=false;$('ion-warning').textContent='Your browser cannot save ion progress.';}if(raw){try{saved=JSON.parse(raw);engine=new IonEngine(saved);}catch{try{localStorage.setItem(key+':unreadable-backup',raw);}catch{}$('ion-warning').hidden=false;$('ion-warning').textContent='Saved ion progress could not be read. A fresh ion session is open.';}}engine??=new IonEngine();engine.next();render();save();}catch(e){$('ion-warning').hidden=false;$('ion-warning').textContent=e.message;}
